// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SecureVault - Multi-sig vault with approval workflow
 * @notice Implements a secure approval-based withdrawal system
 * @dev Uses checks-effects-interactions pattern throughout
 */
contract SecureVault is AccessControl, ReentrancyGuard {
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");

    struct WithdrawalRequest {
        address requester;
        address destination;
        uint256 amount;
        uint256 approvalCount;
        uint256 createdAt;
        bool executed;
        bool cancelled;
    }

    mapping(uint256 => WithdrawalRequest) public requests;
    mapping(uint256 => mapping(address => bool)) public approvals;
    mapping(address => uint256) public balances;
    mapping(address => mapping(address => uint256)) public allowances;

    uint256 public requestCount;
    uint256 public requiredApprovals;
    uint256 public constant REQUEST_EXPIRY = 48 hours;

    event Deposited(address indexed user, uint256 amount);
    event WithdrawalRequested(uint256 indexed requestId, address indexed requester, uint256 amount);
    event WithdrawalApproved(uint256 indexed requestId, address indexed approver);
    event WithdrawalExecuted(uint256 indexed requestId);
    event AllowanceSet(address indexed owner, address indexed spender, uint256 amount);

    constructor(uint256 _requiredApprovals) {
        require(_requiredApprovals >= 2, "Need at least 2 approvals");
        requiredApprovals = _requiredApprovals;
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(OPERATOR_ROLE, msg.sender);
        _grantRole(GUARDIAN_ROLE, msg.sender);
    }

    function deposit() external payable {
        require(msg.value > 0, "Zero deposit");
        balances[msg.sender] += msg.value;
        emit Deposited(msg.sender, msg.value);
    }

    /// @notice Set allowance for a spender to withdraw on your behalf
    function approve(address _spender, uint256 _amount) external {
        require(_spender != address(0), "Zero address");
        allowances[msg.sender][_spender] = _amount;
        emit AllowanceSet(msg.sender, _spender, _amount);
    }

    /// @notice Transfer from another user using allowance
    /// @dev Follows checks-effects-interactions strictly
    function transferFrom(
        address _from,
        address _to,
        uint256 _amount
    ) external nonReentrant {
        require(_to != address(0), "Zero recipient");
        require(_amount > 0, "Zero amount");

        uint256 currentAllowance = allowances[_from][msg.sender];
        require(currentAllowance >= _amount, "Insufficient allowance");
        require(balances[_from] >= _amount, "Insufficient balance");

        // Effects: update all state before any interactions
        allowances[_from][msg.sender] = currentAllowance - _amount;
        balances[_from] -= _amount;
        balances[_to] += _amount;
    }

    /// @notice Owner can increase their own allowance to a spender
    function increaseAllowance(address _spender, uint256 _addedValue) external {
        allowances[msg.sender][_spender] += _addedValue;
        emit AllowanceSet(msg.sender, _spender, allowances[msg.sender][_spender]);
    }

    // === Multi-sig withdrawal system ===

    function requestWithdrawal(
        address _destination,
        uint256 _amount
    ) external onlyRole(OPERATOR_ROLE) returns (uint256) {
        require(_destination != address(0), "Zero destination");
        require(_amount > 0, "Zero amount");
        require(balances[msg.sender] >= _amount, "Insufficient balance");

        uint256 requestId = requestCount++;
        requests[requestId] = WithdrawalRequest({
            requester: msg.sender,
            destination: _destination,
            amount: _amount,
            approvalCount: 0,
            createdAt: block.timestamp,
            executed: false,
            cancelled: false
        });

        emit WithdrawalRequested(requestId, msg.sender, _amount);
        return requestId;
    }

    function approveWithdrawal(uint256 _requestId) external onlyRole(GUARDIAN_ROLE) {
        WithdrawalRequest storage req = requests[_requestId];
        require(!req.executed, "Already executed");
        require(!req.cancelled, "Cancelled");
        require(block.timestamp <= req.createdAt + REQUEST_EXPIRY, "Expired");
        require(!approvals[_requestId][msg.sender], "Already approved");

        approvals[_requestId][msg.sender] = true;
        req.approvalCount++;

        emit WithdrawalApproved(_requestId, msg.sender);
    }

    function executeWithdrawal(uint256 _requestId) external nonReentrant onlyRole(OPERATOR_ROLE) {
        WithdrawalRequest storage req = requests[_requestId];
        require(!req.executed, "Already executed");
        require(!req.cancelled, "Cancelled");
        require(req.approvalCount >= requiredApprovals, "Insufficient approvals");
        require(block.timestamp <= req.createdAt + REQUEST_EXPIRY, "Expired");
        require(balances[req.requester] >= req.amount, "Insufficient balance");

        req.executed = true;
        balances[req.requester] -= req.amount;

        (bool success, ) = req.destination.call{value: req.amount}("");
        require(success, "Transfer failed");

        emit WithdrawalExecuted(_requestId);
    }

    function cancelWithdrawal(uint256 _requestId) external {
        WithdrawalRequest storage req = requests[_requestId];
        require(msg.sender == req.requester || hasRole(GUARDIAN_ROLE, msg.sender), "Not authorized");
        require(!req.executed, "Already executed");
        req.cancelled = true;
    }

    receive() external payable {
        balances[msg.sender] += msg.value;
    }
}
